function norm(t=''){return String(t).toLowerCase().replace(/[أإآ]/g,'ا').replace(/ة/g,'ه').replace(/[ًٌٍَُِّْـ]/g,'').replace(/[^\u0000-\u007F\u0600-\u06FF]+/g,' ').trim()}
