function portableAll(s){return portableCss(s)+(portableExtra[s.category]||'')+(portableSupplement[s.category]||'')+((s.id?.startsWith('JIT-')||s.id?.startsWith('J2-')||s.id?.startsWith('J3-'))?jitterPresetCss:'')+(s.id?.startsWith('DEV-')?devPackCss:'')}
function controlSelector(s){let id='#ui-'+s.id.toLowerCase();if(s.category!=='inputs')return id;if(s.id==='INP-011')return id+' input';if(['INP-012','INP-015'].includes(s.id))return id;return id+' input, '+id+' textarea, '+id+' select'}
function previewTargets(s){let root=el.preview.firstElementChild;if(!root)return[];if(s.category!=='inputs')return[root];if(s.id==='INP-011')return[...root.querySelectorAll('input')];if(['INP-012','INP-015'].includes(s.id))return[root];let nodes=[...root.querySelectorAll('input,textarea,select')];return nodes.length?nodes:[root]}
function rootHtml(s){return s.code.html.replace(/^(\s*)<([a-zA-Z][\w-]*)(\s|>)/,(_,ws,tag,tail)=>ws+'<'+tag+' id="ui-'+s.id.toLowerCase()+'"'+tail)}
function dynamicCss(s){let c=state.controls,sel=controlSelector(s);return `${sel}{${cssRules()}}\n${sel}:focus-visible{outline:2px solid ${c.bg};outline-offset:3px}\n${sel}:hover{transform:scale(${(c.scale/100).toFixed(2)});box-shadow:0 0 ${c.glow}px ${c.bg}88,0 ${Math.round(c.shadow/2)}px ${c.shadow}px rgba(20,25,40,.18)}\n${sel}:active{transform:scale(.98)}\n${sel}:disabled,${sel}[aria-disabled="true"]{opacity:.45;cursor:not-allowed;filter:grayscale(.25)}\n${extraCssRules(s)}`}

function componentJs(s){
  const id='#ui-'+s.id.toLowerCase();
  if(s.id==='CUR-001')return `const root=document.querySelector('${id}');\nconst halo=root.querySelector('span');\nroot.addEventListener('pointermove',e=>{const r=root.getBoundingClientRect();halo.style.left=(e.clientX-r.left)+'px';halo.style.top=(e.clientY-r.top)+'px'});\nroot.addEventListener('pointerleave',()=>{halo.style.left='50%';halo.style.top='50%'});`;
  if(s.id==='INP-018')return `const root=document.querySelector('${id}');\nconst input=root.querySelector('input');\nconst value=root.querySelector('b');\ninput.addEventListener('input',()=>value.textContent=input.value+'%');`;
  if(s.id==='INP-016')return `const root=document.querySelector('${id}');\nconst input=root.querySelector('input[type="file"]');\nconst title=root.querySelector('b');\ninput.addEventListener('change',()=>{title.textContent=input.files?.[0]?.name||'اسحب الملف هنا'});`;
  if(s.id==='MPR-005')return `const root=document.querySelector('${id}');\nconst spot=root.querySelector('i');\nroot.addEventListener('pointermove',e=>{const r=root.getBoundingClientRect();spot.style.left=(e.clientX-r.left)+'px';spot.style.top=(e.clientY-r.top)+'px'});\nroot.addEventListener('pointerleave',()=>{spot.style.left='50%';spot.style.top='50%'});`;
  if(s.id==='INP-019')return `const root=document.querySelector('${id}');\nconst input=root.querySelector('input');\nconst [minus,plus]=root.querySelectorAll('button');\nminus.addEventListener('click',()=>input.value=Math.max(0,(+input.value||0)-1));\nplus.addEventListener('click',()=>input.value=(+input.value||0)+1);`;
  if(s.id==='INP-020')return `const root=document.querySelector('${id}');\nconst input=root.querySelector('input');\nconst items=[...root.querySelectorAll(':scope>div span')];\ninput.addEventListener('input',()=>items.forEach(x=>x.hidden=!x.textContent.toLowerCase().includes(input.value.toLowerCase())));`;
  if(s.id==='TAB-005')return `const root=document.querySelector('${id}');\nconst btn=root.querySelector('button');\nconst panel=root.querySelector(':scope>div');\nbtn.addEventListener('click',()=>panel.hidden=!panel.hidden);`;
  if(s.id==='TAB-006')return `const root=document.querySelector('${id}');\nroot.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>{root.querySelectorAll('button').forEach(x=>x.classList.remove('active'));btn.classList.add('active')}));`;
  if(s.id==='MED-006')return `const root=document.querySelector('${id}');\nconst after=root.querySelector('.after');\nconst line=root.querySelector('i');\nroot.addEventListener('pointermove',e=>{const r=root.getBoundingClientRect();const p=Math.max(0,Math.min(100,(e.clientX-r.left)/r.width*100));after.style.clipPath='inset(0 '+(100-p)+'% 0 0)';line.style.right=(100-p)+'%'});`;
  if(s.id==='MOT-009')return `const stage=document.querySelector('${id}');\nconst tile=stage.querySelector('.drag-tile');\nconst drop=stage.querySelector('.drop-zone');\nlet startX=0,startY=0,baseX=0,baseY=0,dragging=false;\ntile.addEventListener('pointerdown',e=>{dragging=true;startX=e.clientX;startY=e.clientY;tile.setPointerCapture(e.pointerId)});\ntile.addEventListener('pointermove',e=>{if(!dragging)return;const x=baseX+e.clientX-startX,y=baseY+e.clientY-startY;tile.style.transform=\`translate(\${x}px,\${y}px)\`;const a=tile.getBoundingClientRect(),b=drop.getBoundingClientRect();drop.classList.toggle('over',a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top)});\ntile.addEventListener('pointerup',e=>{dragging=false;const a=tile.getBoundingClientRect(),b=drop.getBoundingClientRect(),hit=a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;if(hit){tile.style.opacity='.25';drop.textContent='DONE'}else{baseX=0;baseY=0;tile.style.transform='';drop.classList.remove('over')}tile.releasePointerCapture?.(e.pointerId)});`;
  return '// No JavaScript required for this component.';
}

function code(tab){
  let s=state.active,c=state.controls;if(!s)return'';
  let html=rootHtml(s),css=portableAll(s)+'\n\n'+dynamicCss(s);
  if(tab==='HTML')return '<style>\n'+css+'\n</style>\n'+html;
  if(tab==='CSS')return css;
  if(tab==='JS')return componentJs(s);
  if(tab==='React'){
    let n='Ui'+s.id.replace(/[^a-zA-Z0-9]/g,'');
    return 'const markup = '+JSON.stringify(html)+';\nconst css = '+JSON.stringify(css)+';\n\nexport default function '+n+'(){\n  return (\n    <>\n      <style>{css}</style>\n      <div dangerouslySetInnerHTML={{__html: markup}} />\n    </>\n  );\n}';
  }
  let tw='text-['+c.color+'] bg-['+c.bg+'] rounded-['+c.radius+'px] px-['+c.padding+'px] py-['+Math.round(c.padding*.65)+'px] text-['+c.font+'px] transition-transform duration-['+Math.round(c.speed*10)+'ms] hover:scale-['+(c.scale/100).toFixed(2)+'] active:scale-[.98] aria-disabled:opacity-45 aria-disabled:pointer-events-none';
  return 'const markup = '+JSON.stringify(s.code.html)+';\nconst structuralCss = '+JSON.stringify(portableAll(s))+';\n\nexport default function Ui'+s.id.replace(/[^a-zA-Z0-9]/g,'')+'(){\n  return (\n    <>\n      <style>{structuralCss}</style>\n      <div className="'+tw+'" dangerouslySetInnerHTML={{__html: markup}} />\n    </>\n  );\n}';
}
function renderTabs(){let variants=['HTML','CSS','JS','React','Tailwind'];el.tabs.innerHTML=variants.map(t=>`<button data-tab="${t}" class="${state.tab===t?'active':''}">${t}</button>`).join('');el.code.textContent=code(state.tab);if(el.copyVariant)el.copyVariant.value=state.tab;$('#copyCode').textContent='نسخ '+state.tab}
function applyControls(){let targets=previewTargets(state.active),c=state.controls;if(!targets.length||!c)return;targets.forEach(t=>{t.style.color=c.color;t.style.backgroundColor=c.bg;t.style.borderRadius=c.radius+'px';t.style.padding=`${Math.round(c.padding*.65)}px ${c.padding}px`;t.style.fontSize=c.font+'px';t.style.boxShadow=`0 ${Math.round(c.shadow/2)}px ${c.shadow}px rgba(20,25,40,.18)`;t.style.transition=`transform ${c.speed/100}s ease, box-shadow ${c.speed/100}s ease`;t.onmouseenter=()=>{t.style.transform=`scale(${c.scale/100})`;t.style.boxShadow=`0 0 ${c.glow}px ${c.bg}88,0 ${Math.round(c.shadow/2)}px ${c.shadow}px rgba(20,25,40,.18)`};t.onmouseleave=()=>{t.style.transform='scale(1)';t.style.boxShadow=`0 ${Math.round(c.shadow/2)}px ${c.shadow}px rgba(20,25,40,.18)`}});applyTypeExtras(state.active);el.code.textContent=code(state.tab)}
function updateControls(){let m={cColor:'color',cBg:'bg',cRadius:'radius',cPadding:'padding',cFont:'font',cShadow:'shadow',cGlow:'glow',cScale:'scale',cSpeed:'speed'};Object.entries(m).forEach(([id,k])=>$('#'+id).value=state.controls[k]);$('#vRadius').textContent=state.controls.radius+'px';$('#vPadding').textContent=state.controls.padding+'px';$('#vFont').textContent=state.controls.font+'px';$('#vShadow').textContent=state.controls.shadow;$('#vGlow').textContent=state.controls.glow;$('#vScale').textContent=(state.controls.scale/100).toFixed(2)+'×';$('#vSpeed').textContent=(state.controls.speed/100).toFixed(2)+'s'}
async function copyText(t,msg='تم نسخ الكود'){try{await navigator.clipboard.writeText(t)}catch{let a=document.createElement('textarea');a.value=t;document.body.appendChild(a);a.select();document.execCommand('copy');a.remove()}toast(msg)}
