function showView(v){if(v==='collections'){showCollectionPreset('dashboard');return}state.mode=v;state.cat='all';state.pack='all';state.q='';state.filter='All';resetGridWindow();el.search.value='';let list=[];if(v==='favorites')list=[...state.favorites].map(id=>samples.find(s=>s.id===id)).filter(s=>s&&available(s));else if(v==='recent')list=state.recent.map(id=>samples.find(s=>s.id===id)).filter(s=>s&&available(s));else if(v==='trash')list=[...state.trash].map(id=>samples.find(s=>s.id===id)).filter(s=>s&&!state.purged.has(s.id));renderNav();renderFilters();$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===v));el.title.textContent=v==='favorites'?'المفضلة':v==='recent'?'آخر استخدام':'سلة المحذوفات';el.eyebrow.textContent=v==='trash'?'Trash':'مساحتي';renderGrid(list);header();$('#library').scrollIntoView({behavior:'smooth'});$('#sidebar').classList.remove('open')}
function suggestions(){let q=el.search.value.trim();if(!q){el.suggestions.hidden=true;return}let ts=tokens(q),list=samples.filter(available).map(s=>({s,n:score(s,ts)})).filter(x=>x.n>0).sort((a,b)=>b.n-a.n).slice(0,5);if(!list.length){el.suggestions.hidden=true;return}el.suggestions.innerHTML=list.map(({s})=>`<button data-suggest="${s.id}"><span>${s.name}</span><small>${s.id}</small></button>`).join('');el.suggestions.hidden=false}
